-- Travel Horizon schema. Run in Supabase SQL editor or with `supabase db push`.
create extension if not exists pgcrypto;
create type public.booking_status as enum ('New','Contacted','Confirmed','Cancelled','Completed');
create type public.lead_status as enum ('New','Contacted','Converted','Closed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'tourist' check (role in ('admin','tourist')), created_at timestamptz not null default now());
create table public.destinations (id uuid primary key default gen_random_uuid(), slug text unique not null, region text not null, best_season text, recommended_duration text, difficulty text, activities text[] not null default '{}', highlights text[] not null default '{}', published boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.destination_translations (destination_id uuid references public.destinations(id) on delete cascade, language text not null check(language in ('en','ru','es')), name text not null, short_description text not null, long_description text not null, primary key(destination_id,language));
create table public.tours (id uuid primary key default gen_random_uuid(), slug text unique not null, destination_id uuid references public.destinations(id) on delete set null, price numeric(10,2) not null default 0 check(price>=0), currency text not null default 'USD', duration_days integer not null check(duration_days>0), difficulty text not null, season text, category text not null, included text[] not null default '{}', excluded text[] not null default '{}', itinerary jsonb not null default '[]', published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tour_translations (tour_id uuid references public.tours(id) on delete cascade, language text not null check(language in ('en','ru','es')), title text not null, short_description text not null, overview text not null, faq jsonb not null default '[]', primary key(tour_id,language));
create table public.tour_images (id uuid primary key default gen_random_uuid(), tour_id uuid not null references public.tours(id) on delete cascade, storage_path text not null, alt_text jsonb not null default '{}', sort_order int not null default 0, created_at timestamptz not null default now());
create table public.tour_dates (id uuid primary key default gen_random_uuid(), tour_id uuid not null references public.tours(id) on delete cascade, starts_on date not null, ends_on date not null, capacity int not null default 10 check(capacity>0), booked int not null default 0 check(booked>=0), active boolean not null default true, check(ends_on>=starts_on));
create table public.bookings (id uuid primary key default gen_random_uuid(), tour_id uuid not null references public.tours(id), tour_date_id uuid references public.tour_dates(id), requested_date date not null, adults int not null default 1 check(adults>0), children int not null default 0 check(children>=0), full_name text not null, email text not null, phone text not null, country text, preferred_language text not null default 'en' check(preferred_language in ('en','ru','es')), message text, status public.booking_status not null default 'New', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text, country text, preferred_language text not null default 'en' check(preferred_language in ('en','ru','es')), message text not null, status public.lead_status not null default 'New', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_content (key text primary key, content jsonb not null default '{}', updated_at timestamptz not null default now());
create index tours_published_idx on public.tours(published); create index tours_destination_idx on public.tours(destination_id); create index tour_dates_lookup_idx on public.tour_dates(tour_id, starts_on) where active; create index bookings_status_created_idx on public.bookings(status, created_at desc); create index leads_status_created_idx on public.leads(status, created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.destinations enable row level security; alter table public.destination_translations enable row level security; alter table public.tours enable row level security; alter table public.tour_translations enable row level security; alter table public.tour_images enable row level security; alter table public.tour_dates enable row level security; alter table public.bookings enable row level security; alter table public.leads enable row level security; alter table public.site_content enable row level security;
create policy "Users read own profile" on public.profiles for select using(id=auth.uid()); create policy "Admins manage profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read published destinations" on public.destinations for select using(published or public.is_admin()); create policy "Admins manage destinations" on public.destinations for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read destination translations" on public.destination_translations for select using(exists(select 1 from public.destinations d where d.id=destination_id and (d.published or public.is_admin()))); create policy "Admins manage destination translations" on public.destination_translations for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read published tours" on public.tours for select using(published or public.is_admin()); create policy "Admins manage tours" on public.tours for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read tour translations" on public.tour_translations for select using(exists(select 1 from public.tours t where t.id=tour_id and (t.published or public.is_admin()))); create policy "Admins manage tour translations" on public.tour_translations for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read tour images" on public.tour_images for select using(exists(select 1 from public.tours t where t.id=tour_id and (t.published or public.is_admin()))); create policy "Admins manage tour images" on public.tour_images for all using(public.is_admin()) with check(public.is_admin());
create policy "Public read active dates" on public.tour_dates for select using(active or public.is_admin()); create policy "Admins manage dates" on public.tour_dates for all using(public.is_admin()) with check(public.is_admin());
-- Public inserts allow booking/contact collection; only admins can read/update/delete personal records. Add rate limiting/anti-spam in Edge Functions before launch.
create policy "Public submit booking" on public.bookings for insert with check(true); create policy "Admins read bookings" on public.bookings for select using(public.is_admin()); create policy "Admins update bookings" on public.bookings for update using(public.is_admin()) with check(public.is_admin()); create policy "Admins delete bookings" on public.bookings for delete using(public.is_admin());
create policy "Public submit lead" on public.leads for insert with check(true); create policy "Admins read leads" on public.leads for select using(public.is_admin()); create policy "Admins update leads" on public.leads for update using(public.is_admin()) with check(public.is_admin()); create policy "Admins delete leads" on public.leads for delete using(public.is_admin());
create policy "Public read site content" on public.site_content for select using(true); create policy "Admins manage site content" on public.site_content for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets (id,name,public) values ('tour-images','tour-images',true) on conflict(id) do nothing;
create policy "Public read tour images bucket" on storage.objects for select using(bucket_id='tour-images'); create policy "Admins upload tour images" on storage.objects for insert with check(bucket_id='tour-images' and public.is_admin()); create policy "Admins update tour images" on storage.objects for update using(bucket_id='tour-images' and public.is_admin()) with check(bucket_id='tour-images' and public.is_admin()); create policy "Admins delete tour images" on storage.objects for delete using(bucket_id='tour-images' and public.is_admin());
